local users = tool('list_users', {})
local dates = {"2026-06-15","2026-06-16","2026-06-17","2026-06-18","2026-06-19"}
local result = { users = {}, availability = {} }
for _, u in ipairs(users) do
  result.users[#result.users+1] = { id = u.id, name = u.name }
  result.availability[u.id] = {}
  for _, d in ipairs(dates) do
    local av = tool('get_availability', { user_id = u.id, date = d })
    result.availability[u.id][d] = av.busy or {}
  end
end
return result

